/*
 Problem: 4010. Maximize Pair Strength Using GCD
 Language: cpp
 Runtime: 932 ms (27.18%)
 Memory: 37.3 MB (72.63%)
 Tags: Array, Math, Enumeration, Number Theory
*/
class Solution {
public:
    long long maxPairStrength(vector<int>& nums) {
        long long ans = 0;
        int n = nums.size();

        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                long long g = __gcd(nums[i], nums[j]);
                g *= g;
                ans = max(ans,
                    1LL * nums[i] * nums[j] / g
                );
            }
        }

        return ans;
    }
};
